using System;
using System.Collections.Generic;
using HarmonyLib;
using KSP.UI.Screens;
using Upgradeables;
using UnityEngine;

namespace RPAxe
{
    /// <summary>
    /// Tracking-station DSN tech gate. RP-1 blocked each Deep Space Network facility upgrade behind
    /// a comms tech node (its <c>KCTBUILDINGTECHS { TrackingStation { level = node } }</c>, consumed
    /// by RP0.dll). AXE ships no RP0.dll/KCT, so this Harmony patch re-provides the gate from our own
    /// <c>AXEBUILDINGTECHS</c> node (design/Tree/AxeFacilityGates.cfg, generated by build_tree.py).
    /// The 11-level ladder + per-level DSN gain come from design/Settings/AxeTrackingStation.cfg
    /// (CustomBarnKit @TRACKING); this class only enforces *which tech* unlocks *which level*.
    ///
    /// KSCFacilityContextMenu's own fields (host, UpgradeButton, UpgradeButtonText) are private and
    /// KSP here isn't publicized (unlike RP-1's build), so we read them with Harmony's Traverse.
    /// Two hooks: (1) grey out + relabel the Upgrade button whenever the menu draws; (2) a prefix on
    /// OnUpgradeButtonInput that hard-blocks the click while still gated (no funds spent).
    /// </summary>
    [HarmonyPatch(typeof(KSCFacilityContextMenu))]
    internal static class AxeTrackingStationGate
    {
        // "SpaceCenter/<Facility>" -> (upgrade step (1-based) -> required tech node id)
        private static Dictionary<string, Dictionary<int, string>> _gates;

        private static void EnsureLoaded()
        {
            if (_gates != null) return;
            _gates = new Dictionary<string, Dictionary<int, string>>();
            foreach (ConfigNode root in GameDatabase.Instance.GetConfigNodes("AXEBUILDINGTECHS"))
            {
                foreach (ConfigNode fac in root.nodes)
                {
                    string id = "SpaceCenter/" + fac.name;
                    if (!_gates.TryGetValue(id, out var map))
                        _gates[id] = map = new Dictionary<int, string>();
                    foreach (ConfigNode.Value v in fac.values)
                        if (int.TryParse(v.name, out int lvl))
                            map[lvl] = v.value;
                }
            }
        }

        private static UpgradeableFacility FacilityOf(KSCFacilityContextMenu menu)
        {
            var host = Traverse.Create(menu).Field("host").GetValue<SpaceCenterBuilding>();
            return host != null ? host.Facility : null;
        }

        /// <summary>Tech node gating the facility's NEXT level, or null if that step is ungated or
        /// already researched (i.e. the upgrade is allowed).</summary>
        private static string BlockingTech(UpgradeableFacility fac)
        {
            if (fac == null) return null;
            EnsureLoaded();
            if (!_gates.TryGetValue(fac.id, out var map)) return null;
            if (!map.TryGetValue(fac.FacilityLevel + 1, out string node)) return null;
            return ResearchAndDevelopment.GetTechnologyState(node) == RDTech.State.Available ? null : node;
        }

        private static string TitleOf(string node)
        {
            string t = ResearchAndDevelopment.GetTechnologyTitle(node);
            return string.IsNullOrEmpty(t) ? node : t;
        }

        /// <summary>Smoke-test hook (AutoTest). Confirms the 11-level ladder applied (Piece A), the
        /// AXEBUILDINGTECHS gate table loaded (Piece B), and BlockingTech resolves at the live facility
        /// (Piece C). Expect on a fresh career: tsSteps=10, maxLevel=10, next gate blocked.</summary>
        internal static string SelfTestReport()
        {
            EnsureLoaded();
            int tables = _gates.Count;
            int tsSteps = _gates.TryGetValue("SpaceCenter/TrackingStation", out var m) ? m.Count : 0;
            UpgradeableFacility ts = null;
            foreach (var f in UnityEngine.Object.FindObjectsOfType<UpgradeableFacility>())
                if (f != null && f.id == "SpaceCenter/TrackingStation") { ts = f; break; }
            if (ts == null)
                return "gateTables=" + tables + " tsSteps=" + tsSteps + " — TrackingStation facility NOT FOUND";
            string gate = BlockingTech(ts);
            string gateStr = gate == null ? "none(allowed)" : gate + " [" + TitleOf(gate) + "]";
            return "gateTables=" + tables + " tsSteps=" + tsSteps + " maxLevel=" + ts.MaxLevel +
                   " curLevel=" + ts.FacilityLevel + " nextGate=" + gateStr;
        }

        // --- Grey out + relabel the Upgrade button, on every menu (re)draw. ---
        [HarmonyPostfix]
        [HarmonyPatch("CreateWindowContent")]
        internal static void Post_CreateWindowContent(KSCFacilityContextMenu __instance) => ApplyGate(__instance);

        [HarmonyPostfix]
        [HarmonyPatch("OnFacilityValuesModified")]
        internal static void Post_OnFacilityValuesModified(KSCFacilityContextMenu __instance) => ApplyGate(__instance);

        private static void ApplyGate(KSCFacilityContextMenu menu)
        {
            try
            {
                string node = BlockingTech(FacilityOf(menu));
                if (node == null) return;

                var btn = Traverse.Create(menu).Field("UpgradeButton").GetValue<UnityEngine.UI.Button>();
                if (btn != null) btn.interactable = false;

                // UpgradeButtonText is a TextMeshProUGUI; set .text via reflection to avoid a TMPro
                // compile-time reference. Tells the player *why* at a glance without a click.
                object label = Traverse.Create(menu).Field("UpgradeButtonText").GetValue();
                if (label != null)
                    Traverse.Create(label).Property("text")
                        .SetValue("<color=#ff9900>Requires: " + TitleOf(node) + "</color>");
            }
            catch (Exception e) { Debug.LogError("[AXE] tracking-gate draw: " + e); }
        }

        // --- Hard block: refuse the upgrade click while gated (no funds spent). ---
        [HarmonyPrefix]
        [HarmonyPatch("OnUpgradeButtonInput")]
        internal static bool Pre_OnUpgradeButtonInput(KSCFacilityContextMenu __instance)
        {
            try
            {
                string node = BlockingTech(FacilityOf(__instance));
                if (node == null) return true;   // ungated / researched -> allow the original
                ScreenMessages.PostScreenMessage(
                    "Tracking Station upgrade requires researching " + TitleOf(node) + ".",
                    5f, ScreenMessageStyle.UPPER_CENTER);
                return false;                    // block the upgrade
            }
            catch (Exception e) { Debug.LogError("[AXE] tracking-gate input: " + e); return true; }
        }
    }
}
